def get_l1_for_account(asset_key: str, account_code: str) -> str | None:
    """L1 del (asset, code). Retorna None si no hay match."""
    if not asset_key or not account_code:
        return None
    cat = ASSET_CATALOGS.get(asset_key)
    if not cat:
        return None
    entry = cat['accounts'].get(str(account_code).strip())
    return entry['l1'] if entry else None


def get_l2_for_account(asset_key: str, account_code: str) -> str | None:
    """L2 section del (asset, code). Retorna None si no hay match."""
    if not asset_key or not account_code:
        return None
    cat = ASSET_CATALOGS.get(asset_key)
    if not cat:
        return None
    entry = cat['accounts'].get(str(account_code).strip())
    return entry['l2'] if entry else None